import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for POJONode.equals(Object)
 */
public class POJONode_equals_TriageGen2Test {







    @Test
    public void testEquals_SamePojo() {
        // This test relies on the internal _pojoEquals implementation.
        // Since we cannot mock the protected _pojoEquals easily without PowerMock,
        // we use a standard POJO (String) which has a well-defined equals method.

        String value = "test-string";
        POJONode node1 = new POJONode(value);
        POJONode node2 = new POJONode(value);

        // Covers: if (o instanceof POJONode) -> true, then calls _pojoEquals
        // Assuming _pojoEquals checks the underlying POJO equality
        assertTrue("Nodes with same POJO content should be equal", node1.equals(node2));
    }




}

